/// True when (r, c) is inside the grid and holds land ('#').
fn is_land_at(cells: List[List[Str]], r: Int, c: Int) -> Bool {
  if r < 0 or c < 0 {
    return false
  }
  return match cells.get(r) {
    Some(row) => row.get_or(c, ".") == "#",
    None => false,
  }
}

/// Counts islands: groups of '#' cells connected horizontally or vertically.
pub fn count_islands(grid: List[Str]) -> Int {
  let cells: List[List[Str]] = grid.map(fn(row) => row.chars())
  let rows = cells.len()
  let cols = match cells.get(0) {
    Some(row) => row.len(),
    None => 0,
  }
  let dr = [-1, 1, 0, 0]
  let dc = [0, 0, -1, 1]
  var seen: Map[Str, Bool] = Map {}
  var count = 0
  for r in range(0, rows) {
    for c in range(0, cols) {
      let key = "{r},{c}"
      if is_land_at(cells, r, c) and not seen.has(key) {
        count = count + 1
        seen = seen.set(key, true)
        var stack: List[List[Int]] = [[r, c]]
        while not stack.is_empty() {
          let top = match stack.last() {
            Some(t) => t,
            None => [0, 0],
          }
          stack = stack.remove_at(stack.len() - 1)
          let cr = top.get_or(0, 0)
          let cc = top.get_or(1, 0)
          for d in range(0, 4) {
            let nr = cr + dr.get_or(d, 0)
            let nc = cc + dc.get_or(d, 0)
            let nk = "{nr},{nc}"
            if is_land_at(cells, nr, nc) and not seen.has(nk) {
              seen = seen.set(nk, true)
              stack = stack.push([nr, nc])
            }
          }
        }
      }
    }
  }
  return count
}

